   302  static void sc_asn1_print_utctime(const u8 * buf, size_t buflen)
   303  {
   304          if (buflen < 8) {
   305                  printf("Error in decoding.\n");
   306                  return;
   307          }
   308
   309          print_ascii(buf, 2);            /* YY */
   310          putchar('-');
   311          print_ascii(buf+2, 2);          /* MM */
   312          putchar('-');
   313          print_ascii(buf+4, 2);          /* DD */
   314          putchar(' ');
   315          print_ascii(buf+6, 2);          /* hh */
   316          buf += 8;
   317          buflen -= 8;
   318          if (buflen >= 2 && isdigit(buf[0]) && isdigit(buf[1])) {
   319                  putchar(':');
   320                  print_ascii(buf, 2);    /* mm */
   321                  buf += 2;
   322                  buflen -= 2;
   323          }
   324          if (buflen >= 2 && isdigit(buf[0]) && isdigit(buf[1])) {
   325                  putchar(':');
   326                  print_ascii(buf, 2);    /* ss */
   327                  buf += 2;
   328                  buflen -= 2;
   329          }
   330          if (buflen >= 4 && '.' == buf[0]) {
   331                  print_ascii(buf, 4);    /* fff */
   332                  buf += 4;
   333                  buflen -= 4;
   334          }
   335
   336          if (buflen >= 1 && 'Z' == buf[0]) {
   337                  printf(" UTC");
   338          } else if (buflen >= 5 && ('-' == buf[0] || '+' == buf[0])) {
   339                  putchar(' ');
   340                  print_ascii(buf, 3);    /* +/-hh */
   341                  putchar(':');
   342                  print_ascii(buf+3, 2);  /* mm */
   343          }
   344  }
